#!/usr/bin/env bash
# lint-anti-patterns — hard-block sloppy AI patterns at the commit gate.
#
# Generated by `/install-lint-rails`. Edit freely — checks copied from
# ~/.claude/lint-checks-library/ are now project-local + version-locked.
# Re-run `/install-lint-rails` to pull updates from the library.
#
# Run standalone:        bash scripts/lint-anti-patterns.sh
# Run as part of verify: make verify

set -uo pipefail

ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT" || exit 2

# Conformance work-in-progress marker. During an active stack migration the gate
# will be RED (the deviations ARE the backlog). A `.conformance-wip` file
# downgrades hard failures to warnings so the gate REPORTS the gap without
# blocking commits. Delete the marker once the app first goes green → the gate
# becomes a hard block for that app from then on.
WIP=0
[ -f "$ROOT/.conformance-wip" ] && WIP=1

# Color helpers — only emit ANSI if stdout is a TTY (CI / pipes get plain).
if [ -t 1 ]; then
    R=$'\033[31m'; Y=$'\033[33m'; G=$'\033[32m'; B=$'\033[1m'; X=$'\033[0m'
else
    R=""; Y=""; G=""; B=""; X=""
fi

fail_count=0
warn_count=0
fail() { printf "%s%s✗ %s%s\n" "$R" "$B" "$*" "$X"; fail_count=$((fail_count+1)); }
warn() { printf "%s⚠ %s%s\n" "$Y" "$*" "$X"; warn_count=$((warn_count+1)); }
hdr()  { printf "\n%s═══ %s ═══%s\n" "$B" "$*" "$X"; }
pass() { printf "%s✓ %s%s\n" "$G" "$*" "$X"; }

# Run a single check file. First arg = title, second arg = path to
# check file (relative to repo root), third arg = "fail" or "warn".
# Check files exit 0 = clean, 1 = violations; their stdout = findings.
run_check() {
    local title="$1" path="$2" severity="$3"
    hdr "$title"
    local out rc
    case "$path" in
        *.py) out=$(python3 "$path" 2>&1); rc=$? ;;
        *.sh) out=$(bash "$path" 2>&1); rc=$? ;;
        *)    printf "%s\n" "lint orchestrator: unknown check type: $path"; return 1 ;;
    esac
    if [ "$rc" -eq 0 ] && [ -z "$out" ]; then
        pass "$(basename "$path" | sed 's/\..*//' | tr _ ' '): clean"
    elif [ "$rc" -ne 0 ] && [ "$severity" = "fail" ]; then
        fail "$(basename "$path" | sed 's/\..*//' | tr _ ' '):"
        printf "%s\n" "$out" | sed 's/^/    /'
    elif [ "$severity" = "warn" ] && [ -n "$out" ]; then
        warn "$(basename "$path" | sed 's/\..*//' | tr _ ' '):"
        printf "%s\n" "$out" | sed 's/^/    /'
    elif [ "$rc" -ne 0 ]; then
        fail "$(basename "$path" | sed 's/\..*//' | tr _ ' '):"
        printf "%s\n" "$out" | sed 's/^/    /'
    fi
}

# ===========================================================================
# REGISTERED CHECKS — generated by /install-lint-rails based on detected
# stacks. Add/remove rows freely; each line is a self-contained check call.
# Severity: "fail" blocks the commit; "warn" prints and continues.
# ===========================================================================

# {{CHECKS_BLOCK}}
# Example rows (the skill replaces this comment with the real calls):
# run_check "1. waitForTimeout"           scripts/lint-checks/no_wait_timeout.sh   fail
# run_check "2. Split-locator assertions" scripts/lint-checks/no_split_assert.py   fail
# run_check "3. Section markers"          scripts/lint-checks/section_markers.py   fail
# run_check "4. File growth"              scripts/lint-checks/file_growth.sh       fail
# run_check "5. CODE_MAP drift"           scripts/lint-checks/codemap_drift.py     warn

printf "\n%s═══ Summary ═══%s\n" "$B" "$X"
if [ "$fail_count" -eq 0 ] && [ "$warn_count" -eq 0 ]; then
    printf "%s%slint-anti-patterns: clean%s\n" "$G" "$B" "$X"
    exit 0
fi
printf "%d fail · %d warn\n" "$fail_count" "$warn_count"
if [ "$fail_count" -gt 0 ]; then
    if [ "$WIP" -eq 1 ]; then
        printf "%s%d conformance gap(s) — .conformance-wip present, not blocking%s\n" "$Y" "$fail_count" "$X"
        printf "%sclose them, then 'rm .conformance-wip' to make the gate hard%s\n" "$Y" "$X"
        exit 0
    fi
    printf "%scommit blocked by %d hard violation(s)%s\n" "$R" "$fail_count" "$X"
    exit 1
fi
printf "%swarnings only — commit allowed%s\n" "$Y" "$X"
exit 0
